        "descEn": "Before his death, Abu Bakr nominated Umar ibn al-Khattab as his successor, and the Companions agreed. His caliphate of ten and a half years witnessed the widest Islamic conquests: Damascus (14 AH), Jerusalem (16 AH), Ctesiphon, the Persian capital (16 AH), Egypt (20 AH), and Nihavand (21 AH). Umar ibn al-Khattab personally entered Jerusalem and delivered his famous address to its people, granting them security for their lives, property, and churches — the first document in history granting religious freedom in Jerusalem.",
