        "descEn": "Under Umar, conquests reached their peak: in Syria, Damascus, Homs, Aleppo, and Jerusalem were conquered (under Abu Ubaydah and Khalid). In Iraq, Ctesiphon (the Persian capital) fell after al-Qadisiyyah (16 AH) under Sa'd ibn Abi Waqqas. In Persia, the Persians were finally defeated at Nihavand (21 AH) — 'the conquest of conquests'. In Egypt, Amr ibn al-As conquered Fustat (20 AH) and founded the city of Fustat. Umar established a sophisticated administrative system: registries (diwans), stipends, land tax, and an independent judiciary.",
