        "descAr": "أسس عمر بن الخطاب أول نظام إداري منظم في الإسلام: أنشأ ديوان الجند (لتنظيم العطاء والجيش)، وديوان الخراج (لإدارة أموال الدولة)، وديوان العطاء (للمعاشات). وجعل القضاء مستقلاً عن الخلافة وولّى قضاةً مثل أبي الدرداء وشريح القاضي. ووضع نظاماً عادلاً لخراج الأرض فلم يكلف الناس ما لا يطيقون. كان عمر يطوف بالليل بنفسه يتفقد أحوال الرعية، ومات شهيداً مطعوناً على يد أبي لؤلؤة المجوسي (٢٣ هـ). دفن بجانب النبي ﷺ وأبي بكر. قال عنه النبي ﷺ: 'لو كان بعدي نبي لكان عمر بن الخطاب'.",
        "descEn": "Umar ibn al-Khattab established the first organized administrative system in Islam: the military register (diwan al-jund) for organizing salaries and armies, the land-tax register (diwan al-kharaj), and the stipend register (diwan al-ata'). He made the judiciary independent of the caliphate, appointing judges like Abu al-Darda' and Shurayh al-Qadi. He established a just land-tax system that never burdened people beyond their means. Umar would patrol at night himself, checking on his subjects' conditions. He died a martyr, stabbed by Abu Lu'lu'ah al-Majusi (23 AH), and was buried beside the Prophet and Abu Bakr. The Prophet said: 'If there were to be a prophet after me, it would be Umar ibn al-Khattab.'",
