        "distAr": "من المدينة إلى الكوفة والبصرة والشام ومصر",
        "distEn": "From Madinah to Kufa, Basra, Syria, and Egypt",
        "descAr": "مع ازدياد الفتوحات وانتشار الصحابة في الأمصار، ظهر اختلاف في قراءة القرآن بين أهل الشام والعراق. فأشار حذيفة بن اليمان على عثمان بجمع الناس على مصحف واحد. فأمر عثمان بجمع الصحف التي كانت عند حفصة، واستنساخها في مصحف واحد بلغة قريش، وأرسل نسخاً إلى: الكوفة، والبصرة، والشام، ومصر، وأبقى نسخة في المدينة (المصحف الإمام). وأمر بإحراق ما سواها من المصاحف لئلا يختلف الناس في كتاب الله. هذا العمل العظيم حفظ القرآن من الاختلاف والتحريف، وهو المصحف الذي بين أيدينا حتى اليوم.",
        "descEn": "As conquests increased and Companions spread across the provinces, differences emerged in Qur'anic recitation between the people of Syria and Iraq. Hudhayfah ibn al-Yaman advised Uthman to unite the people on one codex. Uthman ordered the sheets kept with Hafsa to be collected and copied into one codex in the Qurayshi dialect, sending copies to Kufa, Basra, Syria, and Egypt, while keeping one copy in Madinah (the Imam Mushaf). He ordered all other copies burned to prevent division over Allah's Book. This great work preserved the Qur'an from dispute and alteration — it is the same mushaf in our hands today.",
