        "descAr": "في عهد عثمان اتسعت الدولة شرقاً وغرباً: فُتحت أرمينيا وخراسان وطبرستان في الشرق، ودخلت قبائل الترك في الإسلام لأول مرة. وفي الشمال فتحت قبرص (أول فتح بحري في الإسلام) بقيادة معاوية بن أبي سفيان، وأُنشئ لأول مرة أسطول بحري إسلامي لحماية الشواطئ من البيزنطيين. وفي الغرب تم فتح إفريقية (تونس الحالية) بقيادة عبد الله بن سعد بن أبي السرح، وبلغت الفتوحات برقة وطرابلس. وفي عهده انتشر الإسلام في نوبيا وبلاد السودان.",
        "descEn": "Under Uthman, the state expanded east and west: Armenia, Khurasan, and Tabaristan were conquered in the east, and Turkish tribes entered Islam for the first time. In the north, Cyprus was conquered (the first naval conquest in Islam) under Muawiyah ibn Abi Sufyan, and the first Islamic navy was established to protect the coasts from the Byzantines. In the west, North Africa (modern Tunisia) was conquered under Abdullah ibn Sa'd ibn Abi Sarh, reaching Barqah and Tripoli. During his reign, Islam spread into Nubia and the Sudan region.",
