        "descAr": "بدأت الفتنة في آخر خلافته: تجمع أناس من مصر والكوفة والبصرة وطالبوا بعزل بعض الولاة. ثم حاصر الخوارج داره في المدينة ٤٠ يوماً، وهو شيخ كبير يبلغ ٨٢ سنة. رفض أن يقاتلهم خوفاً من إراقة دماء المسلمين، وكان صائماً حين دخلوا عليه من دار أبي حزمة فقتلوه وهو يقرأ القرآن. قال فيه النبي ﷺ: 'يا عثمان إن الله سيقمصك قميصاً، وإنهم يريدون خلعه، فلا تخلعه'. استشهد يوم الجمعة ١٨ ذي الحجة ٣٥ هـ ودفن ليلاً في البقيع، وختمت بوفاته مرحلة الفتوحات الكبرى وتغيرت مسيرة التاريخ.",
        "descEn": "The fitna began in the later years of his caliphate: people from Egypt, Kufa, and Basra gathered demanding the dismissal of some governors. Then the Kharijites besieged his home in Madinah for 40 days. He was an old man of 82. He refused to fight them, fearing Muslim bloodshed. He was fasting when they entered through a neighbor's house and killed him while he was reciting the Qur'an. The Prophet had said: 'O Uthman, Allah will clothe you with a garment, and they will want to take it off — do not take it off.' He was martyred on Friday, 18 Dhul-Hijjah 35 AH, and buried at night in al-Baqi', ending the era of great conquests and altering the course of history.",
