        "distAr": "من المدينة إلى البصرة",
        "distEn": "From Madinah to Basra",
        "descAr": "بعد مقتل عثمان بايعه الناس في المدينة خليفة. لكن بعض الصحابة طالبوا بدم عثمان أولاً (طلحة والزبير وعائشة). خرج علي إلى البصرة لمواجهة الموقف، وجرت بينهم محادثات للصلح كادت تنجح لولا فئة من الخوارج الذين أشعلوا المعركة — معركة الجمل (٣٦ هـ). انتصر علي فيها، لكنه حزن حزناً شديداً لإراقة دماء المسلمين. ثم انتقل إلى الكوفة وجعلها عاصمة خلافته. قال علي: 'اللهم إني أبرأ إليك من دم عثمان، ولقد كنت كارهاً لهذا الأمر'.",
        "descEn": "After Uthman's murder, the people of Madinah pledged allegiance to Ali as caliph. However, some Companions (Talhah, al-Zubayr, and A'ishah) demanded that Uthman's blood be avenged first. Ali went to Basra to address the situation, and negotiations for peace nearly succeeded until a group of Kharijites ignited the battle — the Battle of the Camel (36 AH). Ali emerged victorious but was deeply grieved by the Muslim bloodshed. He then moved to Kufa and made it his capital. Ali said: 'O Allah, I am innocent of Uthman's blood, and I was averse to this matter.'",
        "charsAr": [
          {"i":"🐪","n":"معركة الجمل","r":"دارت بين الصحابة — فتنة دامية"},
          {"i":"📜","n":"طلحة والزبير وعائشة","r":"طالبوا بدم عثمان قبل البيعة"}
        ],
        "charsEn": [
          {"i":"🐪","n":"Battle of the Camel","r":"Fought between Companions — a bloody fitna"},
          {"i":"📜","n":"Talhah, al-Zubayr, A'ishah","r":"Demanded justice for Uthman before allegiance"}
        ],
        "lessonAr": "الفتنة إذا وقعت ذهبت بالحكمة — الصحابة اجتهدوا فأصابوا وأخطأوا والنيات خالصة.",
        "lessonEn": "When fitna strikes, wisdom is lost — the Companions made ijtihad, correct and incorrect, but with pure intentions.",
        "srcs": ["الطبري (٤/٤٦٠)", "ابن كثير (٧/٣٠٠)", "البلاذري (أنساب الأشراف ٢/٢٤٠)"],
