        "descAr": "بعد تنازله عن الخلافة عاد الحسن إلى المدينة المنورة، جوار قبر جده ﷺ ومقام أمه فاطمة. تفرغ للعبادة والعلم والتعليم، وكان مثالاً في الكرم والحلم. قسَم ماله مع الله ثلاث مرات: أخرج نصف ماله في سبيل الله ثم أخرجه كله ثم أخرجه ثلثاً. كان إذا سئل عن شيء أعطاه. وكان شديد الحياء كريم الخلق. عاش في المدينة نحو ٨ سنوات بعد عام الجماعة، ملتزماً ببيته ومسجد جده، لا يتدخل في شؤون الخلافة، صابراً محتسباً.",
        "descEn": "After abdicating the caliphate, al-Hasan returned to Madinah, next to his grandfather's grave and his mother Fatimah's resting place. He devoted himself to worship, knowledge, and teaching, and was a model of generosity and forbearance. He divided his wealth with Allah three times: gave half his wealth, then all of it, then a third. Whenever asked for something, he gave it. He was exceedingly modest and noble in character. He lived in Madinah for about 8 years after the Year of Unity, committed to his home and his grandfather's mosque, not interfering in state affairs, patient and devoted.",
        "charsAr": [
          {"i":"🕌","n":"المدينة المنورة","r":"اعتزاله — جوار قبر النبي ﷺ"},
          {"i":"💎","n":"كرم الحسن","r":"قاسم الله ماله ثلاث مرات"}
        ],
