          "descEn": "Hisham ibn Abd al-Malik assumed the caliphate in 105 AH, becoming the last strong caliph of the Umayyad state. His caliphate lasted 20 years of stability despite numerous revolts and challenges. Hisham was known for his financial and administrative rigor, scrutinizing state accounts and leaving no room for extravagance. During his reign, the Umayyad state reached its greatest geographical extent, and conquests continued at the state's peripheries despite diminishing momentum. He dealt with multiple revolts in Khurasan, the Caucasus, and Asia Minor. However, toward the end of his reign, signs of weakness began to appear: frequent wars drained state resources, and competition within the Umayyad house grew dangerously.",
