          "distAr": "—",
          "distEn": "—",
          "descAr": "انتهت الدولة الأموية بعد 91 عاماً من الحكم، تاركة دروساً عظيمة للأمة الإسلامية. من أبرز أسباب السقوط: غياب الشورى الفعلية في اختيار الحكام، وظهور العصبية القبلية التي مزقت الجيش والمجتمع، وانغماس بعض الخلفاء المتأخرين في الترف والنزاع على السلطة. لكن في المقابل، تركت الدولة الأموية إرثاً عظيماً: فتوحات وصلت فيها حدود الإسلام من الصين إلى فرنسا، وحضارة إسلامية ميزت الهوية العربية الإسلامية، وقبة الصخرة التي لا تزال أيقونة القدس. وأعظم ما تركته: نموذج عمر بن عبد العزيز الذي أثبت أن الحكم الراشدي ممكن حتى في ظل دولة ملكية. إنها قصة أمة تعلمت أن عزتها في إسلامها وعدلها لا في سلطانها.",
          "descEn": "The Umayyad state ended after 91 years of rule, leaving great lessons for the Islamic ummah. Among the most prominent causes of its fall: the absence of genuine consultation (shura) in selecting rulers, the rise of tribal partisanship that tore the army and society apart, and the indulgence of some later caliphs in luxury and power struggles. Yet in return, the Umayyad state left a tremendous legacy: conquests that extended Islam's borders from China to France, an Islamic civilization that defined Arab-Islamic identity, and the Dome of the Rock that remains the icon of Jerusalem. And its greatest legacy: the model of Umar ibn Abd al-Aziz, who proved that righteous governance is possible even within a dynastic state. It is the story of a nation that learned that its glory lies in its Islam and justice, not in its power.",
